//! Pinned exact derivation table for the 936 frozen extraction-gap species
//! identities (`NO_STATIC_POKEMON_SPECIES_CONSTRUCTOR` in
//! `rust/fixtures/m6/raw-source-catalog-v2.json`).
//!
//! The frozen oracle marks these identities as lacking a static species
//! constructor, so their battle metadata cannot compile from oracle bytes.
//! Production resolves every one of them through exactly three pinned
//! construction seams instead, and this table carries the primitive inputs of
//! those seams verbatim so the kernel can re-derive the same content
//! deterministically, fail-closed, and without inventing a single value:
//!
//! 1. [`ErGapSpeciesSource::DumpCustom`] (827 identities): the ER dump drafts
//!    in `src/data/elite-redux/er-species.ts` fed through
//!    `init-elite-redux-custom-species.ts::buildCustomSpecies` - `mapType`
//!    (dump ids 18 "Mystery" / 19 "None" resolve untyped, a null primary then
//!    falls back to NORMAL), the `ER_CUSTOM_SPECIES_WEIGHTS` table with the
//!    pinned 30.0 kg fallback, height pinned to 1.0 m, and the `mapAbilityId`
//!    resolution collapsed to its final pokerogue numeric ids (`0` keeps the
//!    NONE sentinel meaning).
//! 2. [`ErGapSpeciesSource::ContentOf`] (65 identities): exact kit clones -
//!    the regional-variant aliases whose `SPECIES_<KEY>` draft binds through
//!    `ER_ID_MAP.species` to an already extracted (<10000) species, and the
//!    partner eeveelutions cloned verbatim from their base kit by
//!    `injectErNewcomerSpecies`. The copy target resolves from already
//!    compiled entries (extracted oracle bytes or earlier derivations), so
//!    alias content is proven identical to real production content.
//! 3. [`ErGapSpeciesSource::Authored`] (44 identities): hand-authored
//!    definitions - the newcomer roster in
//!    `src/data/elite-redux/er-newcomer-species.ts` and the Discord pitch
//!    roster in `er-fakemon-pitch-species.ts`, pinned at git revision
//!    `4b45344e4003c6c936794296fc27693d884dd493` (the frozen oracle's recorded source positions match this
//!    revision's constant-declaration lines exactly).
//!
//! One identity deserves explicit provenance: species 10685
//! (`INFERNAPE_REDUX_B`) ships an all-zero draft that production's
//! `isDegenerateDraft` gate deliberately refuses to register. Its record
//! still derives verbatim from the pinned draft primitives - all-zero stats,
//! NONE ability slots, the sentinel-type NORMAL fallback - which is exactly
//! what `buildCustomSpecies` computes from that draft; nothing is invented
//! and the production deprecation note travels in the provenance string.
//!
//! Generated from the pinned production sources; do not edit by hand.

use er_types::battle_ids::AbilityId;
use er_types::battle_model::PokemonType;
use thiserror::Error;

use crate::species::SpeciesBaseStats;

/// Exact number of frozen extraction-gap identities covered by this table.
pub const ER_GAP_SPECIES_DERIVATION_COUNT: usize = 936;

/// Height production pins onto every constructed custom species
/// (`buildCustomSpecies` / `registerErEditorMon`: 1.0 m).
pub const ER_GAP_PINNED_HEIGHT_BITS: u64 = 0x3ff0000000000000;

/// Weight production pins when the weights table lacks a dump species
/// (`buildCustomSpecies`: `?? 30.0`).
const ER_DUMP_FALLBACK_WEIGHT_BITS: u64 = 0x403e000000000000;

/// Which pinned production seam a gap identity resolves through.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ErGapSpeciesClass {
    /// ER dump draft through `buildCustomSpecies`.
    DumpCustom,
    /// Kit clone of an already-resolved species entry.
    BaseSpeciesAlias,
    /// Hand-authored newcomer definition.
    AuthoredNewcomer,
    /// Pitch-roster definition (pinned historical revision).
    PitchRoster,
    /// Partner-family kit clone registered by `injectErNewcomerSpecies`.
    SpeciesClone,
}

/// Verbatim primitive inputs of one identity's pinned construction seam.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ErGapSpeciesSource {
    /// Raw ER dump draft. `er_type_*` carry raw dump type ids (sentinels 18 /
    /// 19 and `None` resolve untyped); `ability_ids` are the final pokerogue
    /// numeric ids after the pinned position/dex/id-map translation, where
    /// `0` keeps the NONE sentinel meaning; `weight_table_bits` is the exact
    /// IEEE-754 pattern of the weights-table entry when present.
    DumpCustom {
        draft_index: u32,
        er_type_primary: Option<u8>,
        er_type_secondary: Option<u8>,
        ability_ids: [u64; 3],
        stats: [u32; 6],
        weight_table_bits: Option<u64>,
    },
    /// Exact clone of another species' resolved battle content. The source
    /// always precedes this record (smaller id), enabling single-pass
    /// resolution over ascending catalog order.
    ContentOf(u64),
    /// Hand-authored definition with concrete PokemonType ordinals.
    Authored {
        primary_ordinal: u8,
        secondary_ordinal: Option<u8>,
        stats: [u32; 6],
        ability_ids: [u64; 3],
        weight_bits: u64,
    },
}

/// One fully provenanced extraction-gap identity.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ErGapSpeciesRecord {
    pub id: u64,
    pub key: &'static str,
    pub class: ErGapSpeciesClass,
    /// Human-auditable provenance: pinned source path (plus revision for the
    /// pitch roster) and any seam decision that shaped the record.
    pub provenance: &'static str,
    pub source: ErGapSpeciesSource,
}

/// Typed failure raised while deriving gap-species content.
#[derive(Clone, Copy, Debug, Eq, Error, PartialEq)]
pub enum ErGapDerivationError {
    #[error("gap species ordinal {ordinal} is outside the closed PokemonType enum")]
    UnknownTypeOrdinal { ordinal: u8 },
    #[error("gap species ability numeric id {value} is out of range")]
    UnknownAbilityId { value: u64 },
    #[error(
        "gap species copies the content of species {0}; resolve that identity's own entry first"
    )]
    DeferredContentOf(u64),
}

/// Table-level validation failure.
#[derive(Clone, Debug, Eq, Error, PartialEq)]
pub enum ErGapDerivationValidationError {
    #[error("gap derivation table holds {actual} records, expected 936")]
    RecordCountMismatch { actual: usize },
    #[error(
        "gap derivation record at position {position} breaks strict id ordering ({previous} >= {id})"
    )]
    RecordsOutOfOrder {
        position: usize,
        previous: u64,
        id: u64,
    },
    #[error("gap derivation record {id}: key must not be empty")]
    EmptyKey { id: u64 },
    #[error("gap derivation declares duplicate key `{0}`")]
    DuplicateKey(String),
    #[error(
        "gap derivation record {id}: copy source {source_id} must be a smaller, positive species id resolved earlier"
    )]
    InvalidCopySource { id: u64, source_id: u64 },
    #[error("gap derivation record {id}: class does not match its source seam")]
    ClassSourceMismatch { id: u64 },
    #[error("gap derivation record {id}: {source}")]
    Derivation {
        id: u64,
        source: ErGapDerivationError,
    },
}

const fn r(
    id: u64,
    key: &'static str,
    class: ErGapSpeciesClass,
    provenance: &'static str,
    source: ErGapSpeciesSource,
) -> ErGapSpeciesRecord {
    ErGapSpeciesRecord {
        id,
        key,
        class,
        provenance,
        source,
    }
}

