/// Deterministic lookup over the closed gap-identity set.
pub fn resolve(species_id: u64) -> Option<&'static ErGapSpeciesRecord> {
    let index = ER_GAP_SPECIES_RECORDS
        .binary_search_by(|record| record.id.cmp(&species_id))
        .ok()?;
    Some(&ER_GAP_SPECIES_RECORDS[index])
}

/// Every pinned gap-identity record in frozen catalog order.
pub fn records() -> &'static [ErGapSpeciesRecord] {
    &ER_GAP_SPECIES_RECORDS
}

fn er_dump_type(er_type_id: Option<u8>) -> Option<PokemonType> {
    match er_type_id? {
        0 => Some(PokemonType::Normal),
        1 => Some(PokemonType::Fighting),
        2 => Some(PokemonType::Fire),
        3 => Some(PokemonType::Ice),
        4 => Some(PokemonType::Electric),
        5 => Some(PokemonType::Bug),
        6 => Some(PokemonType::Flying),
        7 => Some(PokemonType::Steel),
        8 => Some(PokemonType::Grass),
        9 => Some(PokemonType::Ground),
        10 => Some(PokemonType::Poison),
        11 => Some(PokemonType::Dark),
        12 => Some(PokemonType::Water),
        13 => Some(PokemonType::Psychic),
        14 => Some(PokemonType::Rock),
        15 => Some(PokemonType::Dragon),
        16 => Some(PokemonType::Ghost),
        17 => Some(PokemonType::Fairy),
        20 => Some(PokemonType::Stellar),
        // Dump sentinels 18 ("Mystery") and 19 ("None") resolve untyped,
        // exactly like `init-elite-redux-custom-species.ts::mapType`.
        _ => None,
    }
}

fn closed_type(ordinal: u8) -> Result<PokemonType, ErGapDerivationError> {
    Ok(match ordinal {
        0 => PokemonType::Normal,
        1 => PokemonType::Fire,
        2 => PokemonType::Water,
        3 => PokemonType::Electric,
        4 => PokemonType::Grass,
        5 => PokemonType::Ice,
        6 => PokemonType::Fighting,
        7 => PokemonType::Poison,
        8 => PokemonType::Ground,
        9 => PokemonType::Flying,
        10 => PokemonType::Psychic,
        11 => PokemonType::Bug,
        12 => PokemonType::Rock,
        13 => PokemonType::Ghost,
        14 => PokemonType::Dragon,
        15 => PokemonType::Dark,
        16 => PokemonType::Steel,
        17 => PokemonType::Fairy,
        18 => PokemonType::Stellar,
        _ => return Err(ErGapDerivationError::UnknownTypeOrdinal { ordinal }),
    })
}

fn ability(value: u64) -> Result<AbilityId, ErGapDerivationError> {
    AbilityId::try_from_u64(value).map_err(|_| ErGapDerivationError::UnknownAbilityId { value })
}

/// Exactly resolved battle content of one gap identity.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ErGapDerivedContent {
    pub stats: SpeciesBaseStats,
    pub base_stat_total: u32,
    pub primary: PokemonType,
    pub secondary: Option<PokemonType>,
    pub weight_bits: u64,
    pub height_bits: u64,
    /// Active ability slot; the NONE sentinel (numeric 0) passes through so
    /// consumers observe exactly what the pinned draft declares.
    pub active_ability: AbilityId,
    /// Passive slots mirroring the frozen two-passive catalog shape.
    pub passives: [Option<AbilityId>; 2],
}

impl ErGapSpeciesRecord {
    /// Purely derives the pinned battle content. [`ErGapSpeciesSource::ContentOf`]
    /// records defer to their source entry, which callers resolve from
    /// already-compiled species metadata.
    pub fn derive_content(&self) -> Result<ErGapDerivedContent, ErGapDerivationError> {
        match &self.source {
            ErGapSpeciesSource::ContentOf(source) => {
                Err(ErGapDerivationError::DeferredContentOf(*source))
            }
            ErGapSpeciesSource::DumpCustom {
                stats,
                er_type_primary,
                er_type_secondary,
                ability_ids,
                weight_table_bits,
                ..
            } => {
                // `buildCustomSpecies`: `mapType(draft.types[0]) ?? NORMAL`,
                // secondary nullable, weights-table lookup with the pinned
                // 30.0 kg fallback, height pinned to 1.0.
                let primary = er_dump_type(*er_type_primary).unwrap_or(PokemonType::Normal);
                let secondary = er_dump_type(*er_type_secondary);
                let weight_bits = weight_table_bits.unwrap_or(ER_DUMP_FALLBACK_WEIGHT_BITS);
                finish(stats, primary, secondary, weight_bits, ability_ids)
            }
            ErGapSpeciesSource::Authored {
                primary_ordinal,
                secondary_ordinal,
                stats,
                ability_ids,
                weight_bits,
            } => {
                let primary = closed_type(*primary_ordinal)?;
                let secondary = match secondary_ordinal {
                    None => None,
                    Some(ordinal) => Some(closed_type(*ordinal)?),
                };
                finish(stats, primary, secondary, *weight_bits, ability_ids)
            }
        }
    }
}

fn finish(
    stats: &[u32; 6],
    primary: PokemonType,
    secondary: Option<PokemonType>,
    weight_bits: u64,
    ability_ids: &[u64; 3],
) -> Result<ErGapDerivedContent, ErGapDerivationError> {
    let base_stats = SpeciesBaseStats {
        hp: stats[0],
        attack: stats[1],
        defense: stats[2],
        special_attack: stats[3],
        special_defense: stats[4],
        speed: stats[5],
    };
    let base_stat_total =
        u32::try_from(stats.iter().map(|stat| u64::from(*stat)).sum::<u64>()).unwrap_or(u32::MAX);
    Ok(ErGapDerivedContent {
        base_stat_total,
        stats: base_stats,
        primary,
        secondary,
        weight_bits,
        height_bits: ER_GAP_PINNED_HEIGHT_BITS,
        active_ability: ability(ability_ids[0])?,
        passives: [
            (ability_ids[1] != 0)
                .then(|| ability(ability_ids[1]))
                .transpose()?,
            (ability_ids[2] != 0)
                .then(|| ability(ability_ids[2]))
                .transpose()?,
        ],
    })
}

/// Validates the whole table: frozen count, strict ordering, key uniqueness,
/// class/source coherence, resolvable copy sources, and per-record
/// derivability. Pure and deterministic.
pub fn validate_derivation() -> Result<(), ErGapDerivationValidationError> {
    if ER_GAP_SPECIES_RECORDS.len() != ER_GAP_SPECIES_DERIVATION_COUNT {
        return Err(ErGapDerivationValidationError::RecordCountMismatch {
            actual: ER_GAP_SPECIES_RECORDS.len(),
        });
    }
    let mut keys = std::collections::BTreeSet::new();
    for (position, record) in ER_GAP_SPECIES_RECORDS.iter().enumerate() {
        if position > 0 {
            let previous = ER_GAP_SPECIES_RECORDS[position - 1].id;
            if previous >= record.id {
                return Err(ErGapDerivationValidationError::RecordsOutOfOrder {
                    position,
                    previous,
                    id: record.id,
                });
            }
        }
        if record.key.is_empty() {
            return Err(ErGapDerivationValidationError::EmptyKey { id: record.id });
        }
        if !keys.insert(record.key) {
            return Err(ErGapDerivationValidationError::DuplicateKey(
                record.key.to_owned(),
            ));
        }
        match (&record.source, record.class) {
            (ErGapSpeciesSource::ContentOf(source), ErGapSpeciesClass::BaseSpeciesAlias)
            | (ErGapSpeciesSource::ContentOf(source), ErGapSpeciesClass::SpeciesClone) => {
                if *source == 0 || *source >= record.id {
                    return Err(ErGapDerivationValidationError::InvalidCopySource {
                        id: record.id,
                        source_id: *source,
                    });
                }
            }
            (ErGapSpeciesSource::DumpCustom { .. }, ErGapSpeciesClass::DumpCustom)
            | (ErGapSpeciesSource::Authored { .. }, ErGapSpeciesClass::AuthoredNewcomer)
            | (ErGapSpeciesSource::Authored { .. }, ErGapSpeciesClass::PitchRoster) => {}
            _ => {
                return Err(ErGapDerivationValidationError::ClassSourceMismatch { id: record.id });
            }
        }
        match record.derive_content() {
            Ok(_) => {}
            Err(ErGapDerivationError::DeferredContentOf(source)) if matches!(record.source, ErGapSpeciesSource::ContentOf(expected) if expected == source) =>
                {}
            Err(source) => {
                return Err(ErGapDerivationValidationError::Derivation {
                    id: record.id,
                    source,
                });
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_validates_and_pins_class_counts() {
        validate_derivation().expect("generated derivation table validates");
        let counts = |class| {
            ER_GAP_SPECIES_RECORDS
                .iter()
                .filter(|record| record.class == class)
                .count()
        };
        assert_eq!(counts(ErGapSpeciesClass::DumpCustom), 827);
        assert_eq!(counts(ErGapSpeciesClass::BaseSpeciesAlias), 54);
        assert_eq!(counts(ErGapSpeciesClass::AuthoredNewcomer), 14);
        assert_eq!(counts(ErGapSpeciesClass::PitchRoster), 30);
        assert_eq!(counts(ErGapSpeciesClass::SpeciesClone), 11);
        assert_eq!(records().len(), ER_GAP_SPECIES_DERIVATION_COUNT);
    }

    #[test]
    fn phantowl_derives_exactly_from_the_pinned_draft() {
        let record = resolve(10_000).expect("PHANTOWL is a pinned dump custom");
        assert_eq!(record.class, ErGapSpeciesClass::DumpCustom);
        let content = record.derive_content().expect("derives");
        assert_eq!(
            content.stats,
            SpeciesBaseStats {
                hp: 105,
                attack: 60,
                defense: 90,
                special_attack: 96,
                special_defense: 126,
                speed: 55,
            }
        );
        assert_eq!(content.base_stat_total, 532);
        assert_eq!(content.primary, PokemonType::Ghost);
        assert_eq!(content.secondary, Some(PokemonType::Flying));
        assert_eq!(content.weight_bits, 0x404F_E666_6666_6666); // 63.8 kg
        assert_eq!(content.height_bits, ER_GAP_PINNED_HEIGHT_BITS); // 1.0 m
        assert_eq!(u64::from(content.active_ability), 110_u64);
        assert_eq!(content.passives[0].map(u64::from), Some(5190_u64));
        assert_eq!(content.passives[1].map(u64::from), Some(5323_u64));
    }

    #[test]
    fn degenerate_infernape_redux_b_derives_verbatim_without_invention() {
        let record = resolve(10_685).expect("INFERNAPE_REDUX_B stays covered");
        let content = record
            .derive_content()
            .expect("derives from the pinned draft");
        assert_eq!(
            content.stats,
            SpeciesBaseStats {
                hp: 0,
                attack: 0,
                defense: 0,
                special_attack: 0,
                special_defense: 0,
                speed: 0,
            }
        );
        // Sentinel dump type 19 ("None") resolves untyped, then the pinned
        // `?? NORMAL` fallback applies, exactly as buildCustomSpecies computes.
        assert_eq!(content.primary, PokemonType::Normal);
        assert_eq!(content.secondary, None);
        assert_eq!(content.active_ability, AbilityId::ZERO);
        assert_eq!(content.passives, [None, None]);
        assert!(record.provenance.contains("isDegenerateDraft"));
    }

    #[test]
    fn aliases_defer_to_their_source_entry() {
        let record = resolve(10_143).expect("RATTATA_ALOLAN alias");
        assert_eq!(record.source, ErGapSpeciesSource::ContentOf(2019));
        assert_eq!(
            record.derive_content(),
            Err(ErGapDerivationError::DeferredContentOf(2019))
        );
    }

    #[test]
    fn authored_pitch_roster_resolves_through_the_pinned_revision() {
        let record = resolve(70_033).expect("Tremburr pitch species");
        assert_eq!(record.class, ErGapSpeciesClass::PitchRoster);
        assert!(record.provenance.contains("pinned revision"));
        let content = record.derive_content().expect("derives");
        assert_eq!(content.primary, PokemonType::Dark);
        assert_eq!(content.secondary, Some(PokemonType::Fighting));
        assert_eq!(content.base_stat_total, 305);
    }
}
